import{_ as t,o as e,c as l,a3 as i}from"./chunks/framework.BTt0kA_k.js";const u=JSON.parse('{"title":"本地数据与版本升级","description":"","frontmatter":{},"headers":[],"relativePath":"user/use/data.md","filePath":"user/use/data.md"}'),r={name:"user/use/data.md"};function d(o,a,s,p,n,h){return e(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="本地数据与版本升级" tabindex="-1">本地数据与版本升级 <a class="header-anchor" href="#本地数据与版本升级" aria-label="Permalink to &quot;本地数据与版本升级&quot;">​</a></h1><h2 id="数据存在哪里" tabindex="-1">数据存在哪里 <a class="header-anchor" href="#数据存在哪里" aria-label="Permalink to &quot;数据存在哪里&quot;">​</a></h2><p>macOS 上，RelayPulse 的本地数据保存在：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Application Support/com.relaypulse.app/</span></span></code></pre></div><p><code>~</code> 表示当前 macOS 用户的个人目录。在 Finder 中选择“前往 → 前往文件夹”，粘贴对应路径即可查找。</p><p>站点、模型、设置和记录摘要保存在 <code>relaypulse.sqlite3</code>。正式探测的请求响应文件、IQ 测试原始流和产物位于该应用数据目录下的各自子目录中。</p><h2 id="api-key-怎样保存" tabindex="-1">API Key 怎样保存 <a class="header-anchor" href="#api-key-怎样保存" aria-label="Permalink to &quot;API Key 怎样保存&quot;">​</a></h2><p>API Key 随站点配置保存在本机，当前没有应用层加密，也未接入系统钥匙串。界面只显示是否已配置，不显示原密钥。</p><p>备份整个应用目录时，备份中也会包含访问凭据。分享诊断包之外的数据库、原始响应或整个数据目录前，应先检查其中包含的内容。</p><h2 id="升级时提示迁移旧版本数据" tabindex="-1">升级时提示迁移旧版本数据 <a class="header-anchor" href="#升级时提示迁移旧版本数据" aria-label="Permalink to &quot;升级时提示迁移旧版本数据&quot;">​</a></h2><p>3.0.1 增加了旧版本数据识别和迁移入口。只有识别到受支持的旧数据格式时，界面才会提供“备份并迁移”。</p><ol><li>退出仍在运行的旧版 RelayPulse，打开新版应用。</li><li>出现“需要迁移旧版本数据”时，阅读界面提示。</li><li>点击“备份并迁移”。</li><li>保持应用运行，等待转换与校验完成。成功后应用会自动重启。</li><li>如果页面停在“数据迁移已完成”，使用“重启应用”。</li><li>重启后核对站点、模型、通知规则和历史记录，并保留原数据目录备份。</li></ol><p>迁移会保留旧数据目录，并转换可识别的配置、访问凭据、规则、历史与关联证据文件。备份路径如在界面中显示，可记录下来。</p><h2 id="迁移受阻或失败怎么办" tabindex="-1">迁移受阻或失败怎么办 <a class="header-anchor" href="#迁移受阻或失败怎么办" aria-label="Permalink to &quot;迁移受阻或失败怎么办&quot;">​</a></h2><p>保留页面错误和旧数据目录，不要手动创建空数据库覆盖原数据。可以在检查原因后使用“重新检查”，并向项目反馈当前版本、之前的版本和完整提示。</p><p>不能识别的旧格式、损坏的数据或不满足校验的数据，会阻止应用进入业务页面。迁移中发生中断时，下次启动会执行恢复检查；以重新打开后的具体提示为准。</p><h2 id="手动备份" tabindex="-1">手动备份 <a class="header-anchor" href="#手动备份" aria-label="Permalink to &quot;手动备份&quot;">​</a></h2><ol><li>通过状态栏菜单退出 RelayPulse，确认应用已结束。</li><li>复制对应的整个应用数据目录到自己的备份位置。</li><li>保留数据库及其附属文件、请求响应文件和 IQ 产物的相对结构。</li></ol><p>完整备份有助于保留记录与证据文件之间的关联。对新版本进行恢复或跨版本搬迁前，先确认目标版本是否支持该数据格式。</p><h2 id="几种清理操作有什么区别" tabindex="-1">几种清理操作有什么区别 <a class="header-anchor" href="#几种清理操作有什么区别" aria-label="Permalink to &quot;几种清理操作有什么区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>删除范围</th></tr></thead><tbody><tr><td>通用设置中清理诊断日志</td><td>本地诊断日志文件</td></tr><tr><td>删除一条正式探测记录</td><td>该记录与对应缓存文件</td></tr><tr><td>清理全部正式探测记录</td><td>所有正式探测记录、对应缓存和相关 Token 统计</td></tr><tr><td>删除一场 IQ 历史运行</td><td>该运行、原始流与产物</td></tr><tr><td>删除站点</td><td>该站点、模型及其独立设置</td></tr></tbody></table><p>诊断包导出不会替代完整数据备份。</p>',22)])])}const b=t(r,[["render",d]]);export{u as __pageData,b as default};
